import React from "react";
import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";
import Login from "./auth/Login";
import Signup from "./auth/Signup";
import JoinRoom from "./components/JoinRoom";
import Lobby from "./components/Lobby";
import Explainer from "./components/Explainer";        // ⬅️ Add this
import Collaboration from "./components/Collaboration";  // ⬅️ Add this

export default function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/" element={<Navigate to="/login" replace />} />
        <Route path="/login" element={<Login />} />
        <Route path="/signup" element={<Signup />} />
        <Route path="/join" element={<JoinRoom />} />
        <Route path="/lobby" element={<Lobby />} />
        <Route path="/explainer" element={<Explainer />} />          {/* ⬅️ Add this */}
        <Route path="/collaboration" element={<Collaboration />} />  {/* ⬅️ Add this */}
        <Route path="*" element={<Navigate to="/login" replace />} />
      </Routes>
    </BrowserRouter>
  );
}
